const days = Number(get(ctx.subject.employment, 'employee_extension_data.days_per_year', ctx.lookup.days_per_year));
const hours = Number(get(ctx.subject.employment, 'terms.normal_hours_per_day', ctx.lookup.normal_hours_per_day));
